/**
 * tools 域实现：SystemOne 调用（官方 SDK 传输 + 总预算超时 + 有限重试 + 并发信号量）。
 *
 * - 基址/模型双写死：JEV_BASE_URL 全地址 pin，SDK 拼 /v1/systemone 故传 root 派生
 *   （漂移即拒绝加载）；JEV_MODEL 别名 jev-latest；加载断言在共享契约，均不接受配置覆盖；
 * - 传输走官方 @typesafe-ai/sdk（构建期 esbuild 内联进 lib，零运行时依赖）：
 *   请求/响应形状与 401/422/429/529 错误分类由 SDK 承载；
 * - FetchImpl 窄面经 toSdkFetch 适配为真实 Response（单测 mock 只改 body，不改形状，全程离线）；
 * - 重试保持旧语义：SDK 单次直试（maxRetries 0），外层按总预算最多 2 次重试（共 3 尝试），
 *   可重试性仍按状态码判定（超时/网络/429/5xx 可重试，其余不重试），重试次数如实回传；
 * - score：SDK 回浮点（legend 0-based），按发送档数线性重缩放到 1..5（round(s/(n-1)*4)+1 再钳制；默认五档即 round+1，旧口径保持）；
 * - tier/automation：上游不再直给，由 confidence 派生（0.8/0.5 双阈，与 UI high 线对齐），
 *   再受预设 automationCap 封顶（封顶逻辑在 service 侧，保持）；
 * - 多题 answers 取首题驱动输出（DecideOutput 单 verdict 形状保持；多题输出后续再议）；
 * - codepoints：usage 是 tokens 非 codepoints，置 0 由 service 回落原文长度；
 * - 状态全部收进闭包/实例，无模块级可变状态。
 */
import {
  APIConnectionError,
  APIError,
  APITimeoutError,
  APIUserAbortError,
  TypeSafeClient,
  TypeSafeError,
} from "@typesafe-ai/sdk";
import type { Questions, ScoreCriteria, SystemOneResult } from "@typesafe-ai/sdk";
import { JEV_BASE_URL } from "../../../shared/interface.ts";
import type { FetchImpl } from "../deps.ts";
import type { ValidQuestion } from "../deps.ts";

/** 上游失败（可重试性由本模块判定，调用方只读 code/category）。 */
export interface DecisionFailure {
  readonly code: string;
  readonly category: string;
  readonly message: string;
  readonly retryable: boolean;
  readonly status?: number;
}

/** 远端原始决议（已做形状校验的最小面）。 */
export interface RemoteVerdict {
  readonly resultKind: "choice" | "score";
  readonly choice?: string;
  readonly score?: number;
  readonly confidence: number;
  readonly tier: number;
  readonly automation: number;
  readonly codepoints: number;
}

/** 默认 fetch 适配（全局 fetch 转窄面；无全局 fetch 即抛未实现）。 */
export function defaultFetchImpl(): FetchImpl {
  return async (url, init) => {
    const impl = (globalThis as unknown as { fetch?: unknown }).fetch;
    if (typeof impl !== "function")
      throw new Error("decision-gateway[500]: global fetch unavailable");
    const res = await (impl as typeof fetch)(url, {
      method: init.method,
      headers: init.headers,
      body: init.body,
      signal: init.signal,
    });
    return { status: res.status, text: await res.text() };
  };
}

/** SDK 拼路径用 root：全地址 pin 派生，后缀漂移即拒绝加载。 */
const SDK_PATH = "/v1/systemone";
if (!JEV_BASE_URL.endsWith(SDK_PATH)) {
  throw new Error("dsh-decision-gateway: JEV_BASE_URL 须以 /v1/systemone 结尾");
}
const JEV_API_ROOT = JEV_BASE_URL.slice(0, -SDK_PATH.length);

/** score legend 五档（SDK 0-based，加 1 回旧 1..5 口径）。 */
const SCORE_LEVELS = ["1", "2", "3", "4", "5"] as const;

/** 请求体（官方 SystemOne 形状：model + 字符串 state + 字典 questions）。 */
export interface DecisionRequestBody {
  readonly model: string;
  readonly state: string;
  readonly questions: Questions;
}

/** confidence 派生分层（0.8 对齐 UI high 线；0.5 低分界）。 */
export function confidenceTier(confidence: number): number {
  if (confidence >= 0.8) return 2;
  if (confidence >= 0.5) return 1;
  return 0;
}

/** 0..1 钳制（非法回落 0）。 */
function clamp01(value: unknown): number {
  return typeof value === "number" && Number.isFinite(value) ? Math.min(1, Math.max(0, value)) : 0;
}

/** 远端问题投影（内部 ValidQuestion 转 SDK 字典；choice criteria 置空描述，score 用自带 levels 或默认数字 legend）。 */
export function toWireQuestions(questions: readonly ValidQuestion[]): Questions {
  const out: Record<string, Questions[string]> = {};
  for (const q of questions) {
    out[q.id] =
      q.kind === "choice"
        ? {
            type: "choice",
            instructions: q.text,
            criteria: Object.fromEntries((q.options ?? []).map((o) => [o, null])),
          }
        : {
            type: "score",
            instructions: q.text,
            // 校验已保证 2-10 档；tuple 形状经 unknown 中转（string[] 无法直接断言为定长元组）。
            criteria: [...(q.levels ?? SCORE_LEVELS)] as unknown as ScoreCriteria,
          };
  }
  return out;
}

/** 调用方取消失败（不可重试：socket 关闭/caller abort 即停，不进重试链）。 */
function callerAbortedFailure(): DecisionFailure {
  return {
    code: "ABORTED",
    category: "aborted",
    message: "caller aborted",
    retryable: false,
  };
}

/** 调用方信号是否已取消（缺席即否）。 */
function isCallerAborted(callerSignal?: AbortSignal): boolean {
  return callerSignal?.aborted === true;
}

/**
 * 融合调用方信号与内部信号（SDK 超时信号）：任一 abort 即取消外调。
 *
 * AbortSignal.any 优先（原子融合），缺席回落手动级联（已 abort 即取已取消侧，
 * 否则建中继控制器双向转发，移除监听防泄漏）。调用方缺席即回内部信号原样。
 */
export function combineSignals(
  callerSignal: AbortSignal | undefined,
  innerSignal: AbortSignal,
): AbortSignal {
  if (callerSignal === undefined) return innerSignal;
  if (callerSignal.aborted) return callerSignal;
  if (innerSignal.aborted) return innerSignal;
  const anyFn = (
    AbortSignal as unknown as { readonly any?: (signals: readonly AbortSignal[]) => AbortSignal }
  ).any;
  if (typeof anyFn === "function") return anyFn([callerSignal, innerSignal]);
  const relay = new AbortController();
  const onAbort = (): void => {
    callerSignal.removeEventListener("abort", onAbort);
    innerSignal.removeEventListener("abort", onAbort);
    relay.abort();
  };
  callerSignal.addEventListener("abort", onAbort, { once: true });
  innerSignal.addEventListener("abort", onAbort, { once: true });
  return relay.signal;
}

/** FetchImpl 窄面转 SDK 可用的真实 Response（init 取方法/头/体/信号，其余丢弃；调用方信号与 SDK 超时信号融合）。 */
function toSdkFetch(
  fetchImpl: FetchImpl,
  callerSignal?: AbortSignal,
): (input: string, init?: RequestInit) => Promise<Response> {
  return async (input, init) => {
    const headers = Object.fromEntries(new Headers(init?.headers ?? {}).entries());
    const inner = init?.signal ?? new AbortController().signal;
    const res = await fetchImpl(input, {
      method: init?.method ?? "POST",
      headers,
      body: typeof init?.body === "string" ? init.body : "",
      signal: combineSignals(callerSignal, inner),
    });
    return new Response(res.text, {
      status: res.status,
      headers: { "content-type": "application/json" },
    });
  };
}

/** 首题答案转 verdict（多题时首题驱动输出；noul/未知形状即 bad-payload 不重试）。 */
export function mapFirstAnswer(
  body: DecisionRequestBody,
  result: SystemOneResult<Questions>,
):
  | { readonly ok: true; readonly verdict: RemoteVerdict }
  | { readonly ok: false; readonly failure: DecisionFailure } {
  const bad = (message: string): { readonly ok: false; readonly failure: DecisionFailure } => ({
    ok: false,
    failure: { code: "UPSTREAM", category: "bad-payload", message, retryable: false },
  });
  const ids = Object.keys(body.questions);
  const first = ids[0];
  const answers: unknown = (result as { readonly answers?: unknown }).answers;
  if (answers === null || typeof answers !== "object" || Array.isArray(answers)) {
    return bad("answers shape");
  }
  const ans: unknown =
    first === undefined ? undefined : (answers as Record<string, unknown>)[first];
  if (ans === null || typeof ans !== "object" || Array.isArray(ans)) {
    return bad("answer shape");
  }
  const rec = ans as Record<string, unknown>;
  if (rec["type"] === "choice") {
    const choice = rec["choice"];
    if (typeof choice !== "string" || choice.length === 0) {
      return bad("choice must be non-empty");
    }
    const confidence = clamp01(rec["confidence"]);
    const level = confidenceTier(confidence);
    return {
      ok: true,
      verdict: {
        resultKind: "choice",
        choice,
        confidence,
        tier: level,
        automation: level,
        codepoints: 0,
      },
    };
  }
  if (rec["type"] === "score") {
    const raw = rec["score"];
    if (typeof raw !== "number" || !Number.isFinite(raw)) {
      return bad("score must be a number");
    }
    const sent = body.questions[first] as { readonly criteria?: readonly unknown[] } | undefined;
    const levels =
      Array.isArray(sent?.criteria) && sent.criteria.length >= 2
        ? sent.criteria.length
        : SCORE_LEVELS.length;
    const score = Math.min(5, Math.max(1, Math.round((raw / (levels - 1)) * 4) + 1));
    const confidence = clamp01(rec["confidence"]);
    const level = confidenceTier(confidence);
    return {
      ok: true,
      verdict: {
        resultKind: "score",
        score,
        confidence,
        tier: level,
        automation: level,
        codepoints: 0,
      },
    };
  }
  return bad("answer type must be choice|score");
}

/** SDK 错误转失败面（状态码沿旧映射；客户端校验错不重试；裸抛错归网络可重试；调用方取消单列 ABORTED 不重试）。 */
export function sdkErrorToFailure(cause: unknown): DecisionFailure {
  if (cause instanceof APIUserAbortError) {
    return callerAbortedFailure();
  }
  if (cause instanceof APITimeoutError) {
    return { code: "TIMEOUT", category: "timeout", message: "request timed out", retryable: true };
  }
  if (cause instanceof APIConnectionError) {
    return {
      code: "NETWORK",
      category: "network",
      message: "fetch failed: " + (cause instanceof Error ? cause.message : String(cause)),
      retryable: true,
    };
  }
  if (cause instanceof APIError) {
    const status = cause.status;
    if (status === 401 || status === 403) {
      return {
        code: "UNAUTHORIZED",
        category: "unauthorized",
        message: "upstream rejected credentials",
        retryable: false,
        status,
      };
    }
    if (status === 429) {
      return {
        code: "RATE_LIMITED",
        category: "rate-limited",
        message: "upstream rate limited",
        retryable: true,
        status,
      };
    }
    if (status >= 500 && status <= 599) {
      return {
        code: "UPSTREAM",
        category: "upstream",
        message: "upstream status " + String(status),
        retryable: true,
        status,
      };
    }
    return {
      code: "UPSTREAM",
      category: "upstream",
      message: "upstream status " + String(status),
      retryable: false,
      status,
    };
  }
  if (cause instanceof Error && cause.name === "AbortError") {
    return { code: "TIMEOUT", category: "timeout", message: "request timed out", retryable: true };
  }
  if (cause instanceof TypeSafeError) {
    return {
      code: "UPSTREAM",
      category: "bad-payload",
      message: "client-side SDK error",
      retryable: false,
    };
  }
  if (cause instanceof Error) {
    return {
      code: "NETWORK",
      category: "network",
      message: "fetch failed: " + cause.message,
      retryable: true,
    };
  }
  return { code: "UPSTREAM", category: "upstream", message: "unknown", retryable: false };
}

/** 调用远端（1 次尝试：SDK 单次直试；抛错经 sdkErrorToFailure 归类；调用方已取消即短路 ABORTED）。 */
async function attemptOnce(
  body: DecisionRequestBody,
  key: string,
  timeoutMs: number,
  fetchImpl: FetchImpl,
  callerSignal?: AbortSignal,
): Promise<
  | { readonly ok: true; readonly verdict: RemoteVerdict }
  | { readonly ok: false; readonly failure: DecisionFailure }
> {
  if (isCallerAborted(callerSignal)) {
    return { ok: false, failure: callerAbortedFailure() };
  }
  if (!(timeoutMs > 0)) {
    return {
      ok: false,
      failure: {
        code: "TIMEOUT",
        category: "timeout",
        message: "request timed out",
        retryable: true,
      },
    };
  }
  const client = new TypeSafeClient({
    apiKey: key,
    baseURL: JEV_API_ROOT,
    fetch: toSdkFetch(fetchImpl, callerSignal),
    logLevel: "warn",
    retry: { maxRetries: 0 },
  });
  try {
    const result = await client.systemOne(
      { model: body.model, state: body.state, questions: body.questions },
      callerSignal === undefined
        ? { timeout: timeoutMs }
        : { timeout: timeoutMs, signal: callerSignal },
    );
    return mapFirstAnswer(body, result);
  } catch (cause) {
    if (isCallerAborted(callerSignal)) {
      return { ok: false, failure: callerAbortedFailure() };
    }
    return { ok: false, failure: sdkErrorToFailure(cause) };
  }
}

/**
 * 有限重试调用（最多 2 次重试；返回重试次数供输出计费面）。
 *
 * timeoutMs 是整次调用的总预算（非逐次）：每次尝试按剩余预算设置 SDK 超时，
 * 预算耗尽后的重试即时失败——慢上游不会把单次决议拖成 3 倍超时（锁定的超时探针
 * 用 timeoutMs=1000 + 2s 轮询钉死该语义：逐次预算下 3 次尝试必超窗）。
 */
export async function callWithRetry(
  body: DecisionRequestBody,
  key: string,
  timeoutMs: number,
  fetchImpl: FetchImpl,
  callerSignal?: AbortSignal,
): Promise<{
  readonly verdict?: RemoteVerdict;
  readonly failure?: DecisionFailure;
  readonly retries: number;
}> {
  const deadline = Date.now() + Math.max(0, timeoutMs);
  const budgetLeft = (): number => Math.max(0, deadline - Date.now());
  const first = await attemptOnce(body, key, budgetLeft(), fetchImpl, callerSignal);
  if (first.ok) return { verdict: first.verdict, retries: 0 };
  if (!first.failure.retryable) return { failure: first.failure, retries: 0 };
  if (first.failure.code === "TIMEOUT") return { failure: first.failure, retries: 0 };
  if (isCallerAborted(callerSignal)) return { failure: callerAbortedFailure(), retries: 0 };
  if (budgetLeft() <= 0) return { failure: first.failure, retries: 0 };
  const second = await attemptOnce(body, key, budgetLeft(), fetchImpl, callerSignal);
  if (second.ok) return { verdict: second.verdict, retries: 1 };
  if (!second.failure.retryable) return { failure: second.failure, retries: 1 };
  if (isCallerAborted(callerSignal)) return { failure: callerAbortedFailure(), retries: 1 };
  if (budgetLeft() <= 0) return { failure: second.failure, retries: 1 };
  const third = await attemptOnce(body, key, budgetLeft(), fetchImpl, callerSignal);
  if (third.ok) return { verdict: third.verdict, retries: 2 };
  return { failure: third.failure, retries: 2 };
}

/**
 * tools 域实现：模型工具定义（ws_request_verdict / ws_list_verdict_guides）。
 *
 * - 注册面只经组合根的 ctx.tools.register 进入宿主；本模块只产出定义；
 * - exec 上下文防御式读取（sessionId/cwd 缺席即回落 unknown/process.cwd()）；
 * - output 附 JSON 渲染（文本块），失败包络同样可读（无概率字段）；
 * - ws_list_verdict_guides 只读（不记录历史、不触网络）。
 */
import type { ToolDefinition, ToolRunContext } from "@deepseek-ai/dsh-tools";
import type { CustomPreset } from "../../../shared/interface.ts";
import type { DecideDeps } from "../deps.ts";
import { decide, listPresets } from "./service.ts";

/** 工具装配（组合根绑定：exec→deps 映射 + 快照取数）。 */
export interface ToolAssembly {
  readonly depsFor: (exec: ToolRunContext) => DecideDeps;
  readonly snapshot: () => {
    readonly isEnabled: (presetId: string) => boolean;
    readonly capOf: (presetId: string) => number;
    readonly customs?: readonly CustomPreset[];
  };
}

/**
 * exec 取 sessionId（多形态防御读取）。
 *
 * 本函数是两处解析规则收敛后的唯一实现（D4）：组合根直接引用本导出，不再自写根侧版本。
 */
export function sessionOf(exec: unknown): string {
  if (exec !== null && typeof exec === "object") {
    const rec = exec as Record<string, unknown>;
    const direct = rec["sessionId"];
    if (typeof direct === "string" && direct.length > 0) return direct;
    for (const key of ["session", "agent"]) {
      const nested = rec[key];
      if (nested !== null && typeof nested === "object") {
        const id = (nested as Record<string, unknown>)["id"];
        if (typeof id === "string" && id.length > 0) return id;
      }
    }
  }
  return "unknown";
}

/** exec 取工作目录（缺席回落进程 cwd；与 sessionOf 同源收敛，见上）。 */
export function rootOf(exec: unknown): string {
  if (exec !== null && typeof exec === "object") {
    const rec = exec as Record<string, unknown>;
    for (const key of ["cwd", "root", "workdir"]) {
      const value = rec[key];
      if (typeof value === "string" && value.length > 0) return value;
    }
  }
  return process.cwd();
}

/** 值转单文本块（失败包络同样 JSON 可读）。 */
function renderJson(
  _args: unknown,
  value: unknown,
): { readonly type: "text"; readonly text: string }[] {
  return [{ type: "text", text: JSON.stringify(value) }];
}

/** 产出两工具定义。 */
export function buildToolDefinitions(assembly: ToolAssembly): ToolDefinition[] {
  const decideTool = {
    name: "ws_request_verdict",
    description:
      "WHEN you must decide rather than generate text, call this after ws_list_verdict_guides: the list tells you which preset is enabled and how to shape questions_override, this tool returns the verdict your code branches on. " +
      "Ask the JEV SystemOne model for a calibrated judgment over text you supply. " +
      "Ask in English when you can: state, instructions and options calibrate best in English; Chinese is fully supported (lang zh) but may return slightly lower confidence. " +
      "USE for three kinds: pick one option from 2-10 candidates (general for a frozen choice, custom for your own choice), rate a plan 1-5 (plan-review for a frozen score, custom for your own score with 2-10 levels), or gate a risky change as safe or risky (risk-check), check text for leaked secrets (secret-leak), or ask any custom question set (custom). " +
      "DO NOT use for open-ended reasoning, writing, or performing actions: this tool only judges and returns a verdict, acting on it is always your decision. " +
      "You MUST supply questions_override on every call (1-20 questions; templates store no questions): choice questions need 2-10 options, score questions must not carry options but may carry levels (2-10 rubric strings, default 1-5, e.g. five levels 1-5 or two levels low-high rescaled to 1-5), question ids and preset_id must be lowercase ASCII letters, digits or hyphens; preset_id is one of the 5 frozen ids or a custom id from ws_list_verdict_guides; lang is en, zh, or unknown and defaults to unknown. " +
      "Texts matching secret shapes (API keys, tokens, private-key blocks, password assignments) never leave the device and return choice human for a person to review; choice Noul likewise means abstention and forces tier none for a person to review. " +
      "A disabled preset fails with PRESET_DISABLED: check availability first with ws_list_verdict_guides. " +
      "Success returns choice or score plus confidence 0-1, tier (none/low/high, derived as confidence \u22650.8 high, \u22650.5 low, else none) and automation (manual/assisted/auto/suggest-only, advisory only: truncated inputs force suggest-only, except local-precheck routing which stays manual). " +
      "Failures carry errorCode and category (for example NO_KEY, UPSTREAM, RATE_LIMITED, TIMEOUT). " +
      "Without a configured key every call fails NO_KEY: ask the user to configure one in settings. " +
      "Enable secret-leak only when you must check untrusted text for real secrets; it stays disabled by default and still runs local precheck first.",
    parameters: {
      type: "object",
      properties: {
        preset_id: {
          type: "string",
          description:
            "Which decision template to apply: one of the 5 frozen ids (general, secret-leak, plan-review, risk-check, custom) or a user-created custom preset id. Frozen ids are fixed; custom ids are the custom:true entries returned by ws_list_verdict_guides. general takes a 2-10-candidate choice; plan-review takes score questions with no options; risk-check takes a proceed-or-not choice (options like safe/risky); secret-leak takes a leaked-or-clean check and is disabled by default; custom takes any 1-20 questions you supply, with the first question driving the verdict.",
        },
        state: {
          type: "object",
          description: "The content under review.",
          properties: {
            text: {
              type: "string",
              description:
                "The text to judge; must be non-blank. Over-long text is truncated (see truncated/originalLength in the verdict).",
            },
            lang: {
              type: "string",
              enum: ["en", "zh", "unknown"],
              default: "unknown",
              description: "Language of text (optional, defaults to unknown; en or zh when known).",
            },
          },
          required: ["text"],
        },
        questions_override: {
          type: "array",
          description:
            "Full question set for this call, 1-20 questions (required; templates store no questions). ids must be unique.",
          items: {
            type: "object",
            properties: {
              id: {
                type: "string",
                description: "Question id: ASCII lowercase letters, digits or hyphens, 1-64 chars.",
              },
              text: {
                type: "string",
                description: "Question text: 1-255 chars, must be non-blank.",
              },
              kind: {
                type: "string",
                enum: ["choice", "score"],
                description: "choice picks one option; score rates 1-5.",
              },
              options: {
                type: "array",
                items: { type: "string" },
                description:
                  "Choice only: 2-10 non-empty options (each 64 chars max). Forbidden on score questions.",
              },
              levels: {
                type: "array",
                items: { type: "string" },
                description:
                  "Score only: 2-10 rubric level descriptions (default 1-5 when omitted). Forbidden on choice questions.",
              },
            },
            required: ["id", "text", "kind"],
          },
        },
      },
      required: ["preset_id", "state", "questions_override"],
    },
    output: {
      schema: { type: "object" },
      render: renderJson,
    },
    isConcurrencySafe: () => true,
    execute: (args: unknown, exec: ToolRunContext) => {
      const base = assembly.depsFor(exec);
      return decide(args, base);
    },
  };
  const listTool = {
    name: "ws_list_verdict_guides",
    description:
      "WHEN you need to know which preset to use or how to shape questions_override, call this first; WHEN NOT to call it is when you already know the enabled preset and its asking conventions. " +
      "List the frozen JEV preset catalogue with live enabled state (read-only: no network, no history). " +
      "Each entry carries its English asking guide (how to shape questions_override for it), templateVersion (always 1) and automationCap (0 manual-only, 1 low, 2 high). " +
      "Call this before ws_request_verdict to check a preset is enabled and to copy its asking conventions; custom:true entries are user-created presets you can also use as preset_id.",
    parameters: { type: "object", properties: {} },
    output: {
      schema: { type: "array" },
      render: renderJson,
    },
    isConcurrencySafe: () => true,
    execute: () => Promise.resolve(listPresets(assembly.snapshot())),
  };
  return [decideTool as ToolDefinition, listTool as ToolDefinition];
}

/**
 * tools 域实现：本地密形预检（命中即不离境、直转人工；纯函数）。
 *
 * secret-leak 预设默认关闭是第一道闸；本预检是第二道——对全部预设生效：
 * 正文命中密钥密形时，本次决议不发任何出境请求，直接返回人工接管。
 */

/** 密钥密形（命中即敏感，宁可误报人工，不可漏报出境）。 */
const SECRET_HIT_PATTERNS: readonly RegExp[] = [
  /sk-[A-Za-z0-9]{8,}/,
  /AKIA[0-9A-Z]{16}/,
  /ghp_[A-Za-z0-9]{8,}/,
  /xox[bpas]-[A-Za-z0-9-]+/,
  /-----BEGIN (?:RSA )?PRIVATE KEY-----/,
  /api[_-]?key\s*[:=]\s*\S+/i,
  /password\s*[:=]\s*\S+/i,
  /secret\s*[:=]\s*\S+/i,
];

/** 是否命中密形（命中即不离境）。 */
export function localPrecheckHit(text: string): boolean {
  for (const pattern of SECRET_HIT_PATTERNS) {
    pattern.lastIndex = 0;
    if (pattern.test(text)) return true;
  }
  return false;
}

/**
 * tools 域实现：连接探针（空体合法；密钥由调用方解析后传入；不记历史）。
 *
 * 从组合根沉入本域（内聚收窄）：探针的远端调用本就是 tools 能力，组合根只做密钥解析与装配。
 */
import type { FetchImpl } from "../deps.ts";
import { callWithRetry, defaultFetchImpl, toWireQuestions } from "./client.ts";
import { JEV_MODEL } from "../../../shared/interface.ts";

/** 探针结果。 */
export type ProbeResult =
  | { readonly ok: true; readonly latencyMs: number }
  | {
      readonly ok: false;
      readonly errorCode: string;
      readonly category: string;
      readonly message: string;
    };

/** 探针输入（key 缺席即 NO_KEY，不触网络）。 */
export interface ProbeInput {
  readonly key: string | undefined;
  readonly timeoutMs: number;
  readonly fetchImpl?: FetchImpl;
}

/** 执行连接探针（general 模板最小体；成功/失败均不记历史）。 */
export async function probeConnection(input: ProbeInput): Promise<ProbeResult> {
  if (input.key === undefined) {
    return { ok: false, errorCode: "NO_KEY", category: "no-key", message: "no api key" };
  }
  const started = Date.now();
  const outcome = await callWithRetry(
    {
      model: JEV_MODEL,
      state: "connection probe",
      questions: toWireQuestions([
        { id: "probe", text: "Reply ok.", kind: "choice", options: ["ok", "fail"] },
      ]),
    },
    input.key,
    input.timeoutMs,
    input.fetchImpl ?? defaultFetchImpl(),
  );
  if (outcome.failure !== undefined || outcome.verdict === undefined) {
    const failure = outcome.failure ?? {
      code: "UPSTREAM",
      category: "upstream",
      message: "unknown",
    };
    return {
      ok: false,
      errorCode: failure.code,
      category: failure.category,
      message: failure.message,
    };
  }
  return { ok: true, latencyMs: Date.now() - started };
}

/** 并发信号量（闭包状态；max≤0 即视同 1）。 */
export function createSemaphore(max: number): {
  readonly run: <T>(task: () => Promise<T>, signal?: AbortSignal) => Promise<T>;
} {
  const limit = Number.isInteger(max) && max > 0 ? max : 1;
  let active = 0;
  const queue: { readonly start: () => void }[] = [];
  const pump = (): void => {
    while (active < limit && queue.length > 0) {
      const next = queue.shift();
      if (next === undefined) return;
      next.start();
    }
  };
  const abortError = (): Error => {
    const error = new Error("operation aborted");
    error.name = "AbortError";
    return error;
  };
  const run = <T>(task: () => Promise<T>, signal?: AbortSignal): Promise<T> => {
    if (signal?.aborted === true) return Promise.reject(abortError());
    return new Promise<T>((resolve, reject) => {
      let settled = false;
      const waiter = {
        start: (): void => {
          if (settled) return;
          settled = true;
          signal?.removeEventListener("abort", onAbort);
          active += 1;
          try {
            void task()
              .then(resolve, reject)
              .finally(() => {
                active -= 1;
                pump();
              });
          } catch (cause) {
            active -= 1;
            pump();
            reject(cause);
          }
        },
      };
      const onAbort = (): void => {
        if (settled) return;
        const index = queue.indexOf(waiter);
        if (index >= 0) queue.splice(index, 1);
        settled = true;
        signal?.removeEventListener("abort", onAbort);
        reject(abortError());
      };
      signal?.addEventListener("abort", onAbort, { once: true });
      queue.push(waiter);
      pump();
    });
  };
  return { run };
}

