/**
 * tools 域实现：decide 编排（校验 → 开关 → 预检 → 截断 → 密钥 → 远端 → 落史）。
 *
 * - 校验 400 不落史（未进入任何预设）；开关关闭不落史；预检命中/远端成败落史；
 * - Noul 置空 tier：choice==="Noul" 时 tier 强制 none（弃权不分级）；
 * - tier/automation 受预设 automationCap 封顶（0=none,1=low,2=high）；
 * - 失败包络无概率字段（choice/score/confidence/tier 一律不出现）；
 * - 计费 codepoints 取远端回值，缺席回落原文长度；重试次数如实回传；
 * - R5：远端成功输出被截断时 automation 强制 suggest-only（local-precheck 的 manual 保持）；
 * - D4：recordEvent 经 safeRecord（try/catch + sessionId 落史前校验回落 unknown），落史失败不污染结果。
 */
import {
  FROZEN_PRESETS,
  JEV_MODEL,
  SESSION_ID_RE,
  TEMPLATE_VERSION,
  truncateCodePoints,
} from "../../../shared/interface.ts";
import type {
  AutomationLevel,
  CustomPreset,
  DecideOutput,
  ErrorEnvelope,
  DecisionTier,
} from "../../../shared/interface.ts";
import type { DecideDeps, DecideEvent } from "../deps.ts";
import { callWithRetry, defaultFetchImpl, toWireQuestions } from "./client.ts";
import { localPrecheckHit } from "./precheck.ts";
import { validateDecideArgs } from "./validate.ts";

/** 失败包络（必含 errorCode + category；message 不带任何原文/密钥）。 */
function envelope(errorCode: string, category: string, message: string): ErrorEnvelope {
  return { ok: false, error: { errorCode, category, message } };
}

/** 等级序号转分层（越界回落 none）。 */
function tierOf(index: number): DecisionTier {
  return index === 2 ? "high" : index === 1 ? "low" : "none";
}

/** 自动化等级（tier none 一律 manual；其余按封顶后序号）。 */
function automationOf(tier: DecisionTier, index: number): AutomationLevel {
  if (tier === "none") return "manual";
  return index >= 2 ? "auto" : index === 1 ? "assisted" : "manual";
}

/** 内部 AbortError 判定（排队取消在 task 启动前由并发门拒绝）。 */
function isAbortError(cause: unknown): boolean {
  return (
    typeof cause === "object" &&
    cause !== null &&
    "name" in cause &&
    (cause as { readonly name?: unknown }).name === "AbortError"
  );
}

/** 落史前 sessionId 校验（非法回落 unknown，保证文件名安全）。 */
function safeSessionId(sessionId: string): string {
  return SESSION_ID_RE.test(sessionId) ? sessionId : "unknown";
}

/** 记录事件（落史失败只记日志，不污染决议结果；sessionId 随事件同行并校验）。 */
function safeRecord(
  deps: DecideDeps,
  event: Omit<DecideEvent, "sessionId"> & { readonly sessionId: string },
): void {
  try {
    deps.recordEvent?.({ ...event, sessionId: safeSessionId(event.sessionId) });
  } catch (cause) {
    deps.logger.warn(
      "dsh-decision-gateway: 历史记录失败 —— " +
        (cause instanceof Error ? cause.message : String(cause)),
    );
  }
}

/** 执行一次决议（纯编排；副作用仅经注入 deps 发生）。 */
export async function decide(
  args: unknown,
  deps: DecideDeps,
): Promise<DecideOutput | ErrorEnvelope> {
  const customMap = deps.customPresets;
  const checked = validateDecideArgs(args, customMap);
  if (!checked.ok)
    return envelope(checked.failure.errorCode, "bad-request", checked.failure.message);
  const valid = checked.valid;
  if (!deps.isEnabled(valid.presetId)) {
    return envelope("PRESET_DISABLED", "preset-disabled", "preset disabled");
  }
  if (deps.signal.aborted) {
    return envelope("ABORTED", "aborted", "caller aborted");
  }

  const direct = <T>(task: () => Promise<T>): Promise<T> => task();
  const limit = deps.limit ?? direct;
  const execute = async (runRemote: typeof direct): Promise<DecideOutput | ErrorEnvelope> => {
    const trunc = truncateCodePoints(valid.text, deps.connection.truncBudget);
    const now = deps.now ?? Date.now;
    const cap = deps.capOf(valid.presetId);
    const started = now();
    const hit = localPrecheckHit(valid.text);
    if (hit) {
      safeRecord(deps, {
        sessionId: deps.sessionId,
        precheckHit: true,
        presetId: valid.presetId,
        text: valid.text,
        lang: valid.lang,
        truncated: trunc.truncated,
        originalLength: trunc.originalLength,
        resultKind: "local-precheck",
        questions: valid.questions,
        choice: "human",
        confidence: 1,
        tier: "none",
        automation: "manual",
        latencyMs: 0,
      });
      return {
        ok: true,
        provider: "official",
        appliedSource: "local-precheck",
        truncated: trunc.truncated,
        originalLength: trunc.originalLength,
        tier: "none",
        automation: "manual",
        codepoints: 0,
        retries: 0,
        latencyMs: 0,
        resultKind: "local-precheck",
        choice: "human",
        confidence: 1,
      };
    }
    const resolved = deps.resolveKey();
    if (resolved.key === undefined) {
      safeRecord(deps, {
        sessionId: deps.sessionId,
        presetId: valid.presetId,
        text: valid.text,
        lang: valid.lang,
        truncated: trunc.truncated,
        originalLength: trunc.originalLength,
        resultKind: "not-executed",
        questions: valid.questions,
        precheckHit: hit,
        confidence: 0,
        tier: "none",
        automation: "manual",
        latencyMs: 0,
        errorCode: "NO_KEY",
      });
      return envelope("NO_KEY", "no-key", "no api key (set apiKeyRef or plaintext)");
    }
    const fetchImpl = deps.fetchImpl ?? defaultFetchImpl();
    const body = {
      model: JEV_MODEL,
      state: trunc.text,
      questions: toWireQuestions(valid.questions),
    };
    const outcome = await runRemote(() =>
      callWithRetry(
        body,
        resolved.key as string,
        deps.connection.timeoutMs,
        fetchImpl,
        deps.signal,
      ),
    );
    const latencyMs = now() - started;
    if (outcome.failure !== undefined || outcome.verdict === undefined) {
      const failure = outcome.failure ?? {
        code: "UPSTREAM",
        category: "upstream",
        message: "unknown",
      };
      safeRecord(deps, {
        sessionId: deps.sessionId,
        presetId: valid.presetId,
        text: valid.text,
        lang: valid.lang,
        truncated: trunc.truncated,
        originalLength: trunc.originalLength,
        resultKind: "upstream-error",
        questions: valid.questions,
        precheckHit: hit,
        confidence: 0,
        tier: "none",
        automation: "manual",
        latencyMs,
        errorCode: failure.code,
      });
      return envelope(failure.code, failure.category, failure.message);
    }
    const verdict = outcome.verdict;
    const tierIndex =
      verdict.resultKind === "choice" && verdict.choice === "Noul"
        ? 0
        : Math.min(verdict.tier, cap);
    const autoIndex = Math.min(verdict.automation, cap);
    const tier = tierOf(tierIndex);
    const automation: AutomationLevel = trunc.truncated
      ? "suggest-only"
      : automationOf(tier, autoIndex);
    const codepoints = verdict.codepoints > 0 ? verdict.codepoints : trunc.originalLength;
    safeRecord(deps, {
      sessionId: deps.sessionId,
      presetId: valid.presetId,
      text: valid.text,
      lang: valid.lang,
      truncated: trunc.truncated,
      originalLength: trunc.originalLength,
      resultKind: verdict.resultKind,
      questions: valid.questions,
      precheckHit: hit,
      ...(verdict.choice !== undefined ? { choice: verdict.choice } : {}),
      ...(verdict.score !== undefined ? { score: verdict.score } : {}),
      confidence: verdict.confidence,
      tier,
      automation,
      latencyMs,
    });
    return {
      ok: true,
      provider: "official",
      appliedSource: valid.appliedSource,
      truncated: trunc.truncated,
      originalLength: trunc.originalLength,
      tier,
      automation,
      codepoints,
      retries: outcome.retries,
      latencyMs,
      resultKind: verdict.resultKind,
      ...(verdict.choice !== undefined ? { choice: verdict.choice } : {}),
      ...(verdict.score !== undefined ? { score: verdict.score } : {}),
      confidence: verdict.confidence,
    };
  };

  try {
    return await limit(() => execute(direct), deps.signal);
  } catch (cause) {
    if (isAbortError(cause)) {
      return envelope("ABORTED", "aborted", "caller aborted");
    }
    throw cause;
  }
}

/** 预设清单（只读；frozen 规范 + 自建 customs，开关/上限取配置快照）。 */
export function listPresets(deps: {
  readonly isEnabled: (presetId: string) => boolean;
  readonly capOf: (presetId: string) => number;
  readonly customs?: readonly CustomPreset[];
}): readonly {
  readonly id: string;
  readonly enabled: boolean;
  readonly templateVersion: 1;
  readonly automationCap: number;
  readonly label: string;
  readonly description: string;
  readonly custom: boolean;
}[] {
  const frozen = FROZEN_PRESETS.map((preset) => ({
    id: preset.id,
    enabled: deps.isEnabled(preset.id),
    templateVersion: TEMPLATE_VERSION as 1,
    automationCap: deps.capOf(preset.id),
    label: preset.label,
    description: preset.description,
    custom: false as const,
  }));
  const customs = (deps.customs ?? []).map((preset) => ({
    id: preset.id,
    enabled: deps.isEnabled(preset.id),
    templateVersion: TEMPLATE_VERSION as 1,
    automationCap: deps.capOf(preset.id),
    label: preset.label,
    description: preset.description,
    custom: true as const,
  }));
  return [...frozen, ...customs];
}

/**
 * tools 域实现：ws_request_verdict 参数校验（纯函数）。
 *
 * 规则（任务契约；模板零考题）：
 * - 双缺省/空串/空数组 400：preset_id 缺省、state.text 缺省或空串、全员缺 override、override 空数组；
 * - 全员显式带题：questions_override 必填（1-20 题任意），appliedSource 为 custom（custom 内建或自建 id）或 override（其余）；
 * - 互斥：题 id 唯一；choice 必须带 options（2-10 个非空串），score 禁止带 options；
 * - 255/长度：单题文本 1-255 codepoints，id ASCII 且 ≤64，总题数 ≤20；
 * - 中文 400：preset/question id 含 CJK 即 400（state 正文不受此限，lang=zh 合法）；
 * - lang 无缺省：en|zh|unknown 必填其一。
 */
import {
  MAX_QUESTIONS,
  MAX_QUESTION_TEXT,
  PRESET_ID_RE,
  QUESTION_ID_RE,
  containsCjk,
  frozenPresetOf,
} from "../../../shared/interface.ts";
import type { CustomPreset } from "../../../shared/interface.ts";
import type { ValidDecide, ValidQuestion } from "../deps.ts";

/** 校验失败（调用方映射为 400/ErrorEnvelope，不抛）。 */
export interface DecideValidationFailure {
  readonly errorCode: string;
  readonly message: string;
}

type Invalid = { readonly ok: false; readonly failure: DecideValidationFailure };

function fail(errorCode: string, message: string): Invalid {
  return { ok: false, failure: { errorCode, message } };
}

function isRecord(value: unknown): value is Record<string, unknown> {
  return value !== null && typeof value === "object" && !Array.isArray(value);
}

/** 单题校验（kind/options 互斥 + 255 + ASCII id）。 */
function checkQuestion(
  item: unknown,
): { readonly ok: true; readonly question: ValidQuestion } | Invalid {
  if (!isRecord(item)) return fail("BAD_QUESTION", "question must be an object");
  const id: unknown = item["id"];
  const text: unknown = item["text"];
  const kind: unknown = item["kind"];
  if (typeof id !== "string" || id.length === 0 || !QUESTION_ID_RE.test(id) || containsCjk(id)) {
    return fail("BAD_QUESTION_ID", "question id must be ASCII a-z0-9- 1..64");
  }
  if (
    typeof text !== "string" ||
    Array.from(text).length === 0 ||
    Array.from(text).length > MAX_QUESTION_TEXT ||
    text.trim().length === 0
  ) {
    return fail("BAD_QUESTION_TEXT", "question text must be 1..255 codepoints and non-blank");
  }
  if (kind !== "choice" && kind !== "score") {
    return fail("BAD_QUESTION_KIND", "question kind must be choice|score");
  }
  const options: unknown = item["options"];
  if (kind === "choice") {
    if (!Array.isArray(options) || options.length < 2 || options.length > 10) {
      return fail("BAD_OPTIONS", "choice question needs 2..10 options");
    }
    for (const opt of options as unknown[]) {
      if (
        typeof opt !== "string" ||
        opt.length === 0 ||
        Array.from(opt).length > 64 ||
        (opt as string).trim().length === 0
      ) {
        return fail("BAD_OPTIONS", "option must be non-empty string <=64 codepoints");
      }
    }
    if (item["levels"] !== undefined) {
      return fail("BAD_LEVELS", "choice question must not carry levels");
    }
    const opts = (options as unknown[]).map((opt) => opt as string);
    return { ok: true, question: { id, text, kind, options: opts } };
  }
  if (options !== undefined) {
    return fail("BAD_OPTIONS", "score question must not carry options");
  }
  const levels: unknown = item["levels"];
  if (levels === undefined) return { ok: true, question: { id, text, kind } };
  if (!Array.isArray(levels) || levels.length < 2 || levels.length > 10) {
    return fail(
      "BAD_LEVELS",
      "score levels must be 2..10 rubric strings (or omit for default 1-5)",
    );
  }
  for (const lv of levels as unknown[]) {
    if (
      typeof lv !== "string" ||
      lv.length === 0 ||
      Array.from(lv).length > 64 ||
      (lv as string).trim().length === 0
    ) {
      return fail("BAD_LEVELS", "level must be non-empty string <=64 codepoints");
    }
  }
  return {
    ok: true,
    question: { id, text, kind, levels: (levels as unknown[]).map((lv) => lv as string) },
  };
}

/** override 数组校验（非空 + 题数上限 + id 唯一）。 */
function checkOverrideList(
  raw: unknown,
): { readonly ok: true; readonly questions: ValidQuestion[] } | Invalid {
  if (!Array.isArray(raw) || raw.length === 0) {
    return fail("EMPTY_OVERRIDE", "questions_override must be a non-empty array");
  }
  if (raw.length > MAX_QUESTIONS) {
    return fail("TOO_MANY_QUESTIONS", "questions_override must hold <=20 questions");
  }
  const questions: ValidQuestion[] = [];
  const seen = new Set<string>();
  for (const item of raw as unknown[]) {
    const checked = checkQuestion(item);
    if (!checked.ok) return checked;
    if (seen.has(checked.question.id)) {
      return fail("DUPLICATE_QUESTION_ID", "question ids must be unique");
    }
    seen.add(checked.question.id);
    questions.push(checked.question);
  }
  return { ok: true, questions };
}

/** ws_request_verdict 参数校验（成功即 ValidDecide，失败即 400 类错误；custom 自建 id 经第二参传入）。 */
export function validateDecideArgs(
  args: unknown,
  custom?: ReadonlyMap<string, CustomPreset>,
): { readonly ok: true; readonly valid: ValidDecide } | Invalid {
  if (!isRecord(args)) return fail("BAD_ARGS", "args must be an object");
  const presetRaw: unknown = args["preset_id"];
  if (typeof presetRaw !== "string" || presetRaw.length === 0) {
    return fail("MISSING_PRESET", "preset_id is required");
  }
  if (!PRESET_ID_RE.test(presetRaw) || containsCjk(presetRaw)) {
    return fail("BAD_PRESET_ID", "preset_id must be ASCII a-z0-9- 1..64");
  }
  const template = frozenPresetOf(presetRaw);
  const customPreset = template === undefined ? custom?.get(presetRaw) : undefined;
  if (template === undefined && customPreset === undefined) {
    return fail("UNKNOWN_PRESET", "unknown preset");
  }
  const state: unknown = args["state"];
  if (!isRecord(state)) return fail("MISSING_STATE", "state is required");
  const text: unknown = state["text"];
  if (typeof text !== "string" || text.length === 0 || (text as string).trim().length === 0) {
    return fail("EMPTY_TEXT", "state.text must be a non-blank string");
  }
  const langRaw: unknown = state["lang"];
  const lang: "en" | "zh" | "unknown" =
    langRaw === undefined ? "unknown" : (langRaw as "en" | "zh" | "unknown");
  if (lang !== "en" && lang !== "zh" && lang !== "unknown") {
    return fail("BAD_LANG", "state.lang must be en|zh|unknown");
  }
  const override: unknown = args["questions_override"];
  if (override === undefined) {
    return fail("MISSING_OVERRIDE", "questions_override is required (templates hold no questions)");
  }
  const checked = checkOverrideList(override);
  if (!checked.ok) return checked;
  return {
    ok: true,
    valid: {
      presetId: presetRaw,
      text,
      lang,
      questions: checked.questions,
      appliedSource: presetRaw === "custom" || customPreset !== undefined ? "custom" : "override",
    },
  };
}

