/** 本地预检不离境：全密形命中即 local-precheck 且 fetch 零调用（全离线；全局 fetch 桩为例外，直连默认 fetch 旁路验证）。
 *
 * 守的是 tools/precheck.localPrecheckHit + service.decide 的预检短路：把任一密形删掉、
 * 短路移到密钥之后、忘记计数 fetch，本文件必红。fetch 经注入计数，落盘无。
 */
import { describe, expect, it } from "vitest";
import { decide } from "../../src/server/tools/impl/service.ts";
import { localPrecheckHit } from "../../src/server/tools/impl/precheck.ts";
import type { DecideDeps } from "../../src/server/tools/deps.ts";

const CONNECTION = {
  timeoutMs: 8000,
  maxConcurrency: 4,
  truncBudget: 32000,
  hasPlaintextKey: false,
} as const;

function baseDeps(over: Partial<DecideDeps> = {}): DecideDeps {
  return {
    logger: { warn: () => {} },
    connection: { ...CONNECTION },
    isEnabled: () => true,
    capOf: () => 2,
    resolveKey: () => ({ key: "Abcdefgh12345678", source: "env" as const }),
    root: "/tmp/proj",
    sessionId: "sess-1",
    signal: new AbortController().signal,
    ...over,
  };
}

const SECRETS: readonly string[] = [
  "key sk-Abcdef12345678 here",
  "token AKIAIOSFODNN7EXAMPLE here",
  "ghp_abcdefgh12345678 leak",
  "xoxb-1234-abcd token",
  "-----BEGIN PRIVATE KEY-----\nMIIB\n-----END PRIVATE KEY-----",
  "api_key: hunter2-value",
  "password=hunter2",
  "secret: topsecret123",
];

describe("secret-leak 本地预检命中不离境", () => {
  it("残缺不命中、残头命中（打红点：{8,}/{16}/+/[:=] 量词）", () => {
    for (const frag of [
      "sk-",
      "sk-Abc12",
      "AKIA",
      "ghp_",
      "xoxb-",
      "password",
      "password=",
      "api_key: ",
    ]) {
      expect(localPrecheckHit(frag)).toBe(false);
    }
    expect(localPrecheckHit("-----BEGIN PRIVATE KEY-----")).toBe(true);
    expect(localPrecheckHit("-----BEGIN RSA PRIVATE KEY-----")).toBe(true);
  });
  it("全密形命中；干净文本不命中", () => {
    for (const raw of SECRETS) expect(localPrecheckHit(raw)).toBe(true);
    expect(localPrecheckHit("today is sunny")).toBe(false);
    expect(localPrecheckHit("hello world")).toBe(false);
  });
  it.each(SECRETS)("命中 %s 即 local-precheck 且 fetch 零调用", async (secretText) => {
    let calls = 0;
    const events: unknown[] = [];
    const out = await decide(
      {
        preset_id: "general",
        state: { text: "prefix " + secretText + " suffix", lang: "en" },
        questions_override: [{ id: "q1", text: "Pick one.", kind: "choice", options: ["A", "B"] }],
      },
      baseDeps({
        fetchImpl: async () => {
          calls += 1;
          return { status: 200, text: "{}" };
        },
        recordEvent: (e) => {
          events.push(e);
        },
      }),
    );
    expect(calls).toBe(0);
    expect(out).toMatchObject({
      ok: true,
      provider: "official",
      appliedSource: "local-precheck",
      tier: "none",
      automation: "manual",
    });
    expect(events).toHaveLength(1);
  });
  it("禁用预设优先于预检：secret-leak 关闭即 PRESET_DISABLED（不走 local-precheck）", async () => {
    let calls = 0;
    const out = await decide(
      {
        preset_id: "secret-leak",
        state: { text: "my sk-Abcdef12345678 leak", lang: "en" },
        questions_override: [{ id: "q1", text: "Pick one.", kind: "choice", options: ["A", "B"] }],
      },
      baseDeps({
        isEnabled: (id) => id !== "secret-leak",
        fetchImpl: async () => {
          calls += 1;
          return { status: 200, text: "{}" };
        },
      }),
    );
    expect(calls).toBe(0);
    expect(out.ok).toBe(false);
    if (!out.ok) expect(out.error.errorCode).toBe("PRESET_DISABLED");
  });
  it("全局 fetch 桩亦零调用：预检短路不经过默认 fetch", async () => {
    const prev = (globalThis as unknown as { fetch?: unknown }).fetch;
    let globalCalls = 0;
    (globalThis as unknown as { fetch: unknown }).fetch = async () => {
      globalCalls += 1;
      throw new Error("must not egress");
    };
    try {
      let calls = 0;
      const out = await decide(
        {
          preset_id: "general",
          state: { text: "leak sk-Abcdef12345678", lang: "en" },
          questions_override: [
            { id: "q1", text: "Pick one.", kind: "choice", options: ["A", "B"] },
          ],
        },
        baseDeps({
          fetchImpl: async () => {
            calls += 1;
            return { status: 200, text: "{}" };
          },
        }),
      );
      expect(calls).toBe(0);
      expect(globalCalls).toBe(0);
      expect(out).toMatchObject({ ok: true, appliedSource: "local-precheck" });
    } finally {
      if (prev === undefined) delete (globalThis as unknown as { fetch?: unknown }).fetch;
      else (globalThis as unknown as { fetch: unknown }).fetch = prev;
    }
  });
  it("无 key 与禁用同样不触网且包络结构化", async () => {
    let calls = 0;
    const noKey = await decide(
      {
        preset_id: "general",
        state: { text: "hi", lang: "en" },
        questions_override: [{ id: "q1", text: "Pick one.", kind: "choice", options: ["A", "B"] }],
      },
      baseDeps({
        resolveKey: () => ({ key: undefined, source: "none" as const }),
        fetchImpl: async () => {
          calls += 1;
          return { status: 200, text: "{}" };
        },
      }),
    );
    expect(calls).toBe(0);
    expect(noKey.ok).toBe(false);
    if (!noKey.ok) {
      expect(noKey.error.errorCode).toBe("NO_KEY");
      expect(typeof noKey.error.category).toBe("string");
    }
  });
});

/** 工具描述面单测（全离线；锁模型可见契约的名实一致）。
 *
 * 守的是 buildToolDefinitions 产出的 name/description/parameters（DSH 只把这三面送给模型）：
 * 描述退化成一句话、参数缺 enum/items 说明、必填项丢失，任一改动本文件必红。
 * 不锁逐字文案，只锁契约名词与结构（改措辞不红，删含义才红）。
 */
import { describe, expect, it } from "vitest";
import { buildToolDefinitions } from "../../src/server/tools/impl/define.ts";
import type { DecideDeps } from "../../src/server/tools/deps.ts";

function deps(): DecideDeps {
  return {
    logger: { warn: () => {} },
    connection: { timeoutMs: 8000, maxConcurrency: 4, truncBudget: 32000, hasPlaintextKey: false },
    isEnabled: () => true,
    capOf: () => 2,
    resolveKey: () => ({ key: "Abcdefgh12345678", source: "env" as const }),
    root: "/tmp/proj",
    sessionId: "sess-1",
    signal: new AbortController().signal,
  };
}

function definitions() {
  return buildToolDefinitions({
    depsFor: () => deps(),
    snapshot: () => ({ isEnabled: () => true, capOf: () => 2 }),
  });
}

function paramsOf(name: string): Record<string, unknown> {
  const tool = definitions().find((d) => d.name === name);
  expect(tool).toBeDefined();
  return (tool as unknown as { parameters: Record<string, unknown> }).parameters;
}

describe("decide 描述覆盖契约", () => {
  it("讲清何时用、何时不用、必带题目与失败语义", () => {
    const tool = definitions().find((d) => d.name === "ws_request_verdict");
    expect(tool).toBeDefined();
    const text = (tool as unknown as { description: string }).description;
    for (const noun of [
      "questions_override",
      "PRESET_DISABLED",
      "ws_list_verdict_guides",
      "suggest-only",
      "NO_KEY",
      "English",
      "DO NOT use",
    ]) {
      expect(text).toContain(noun);
    }
  });
  it("描述非一句话：长度下限锁详细度", () => {
    const tool = definitions().find((d) => d.name === "ws_request_verdict");
    const text = (tool as unknown as { description: string }).description;
    expect(text.length).toBeGreaterThanOrEqual(500);
  });
});

describe("decide 参数面自描述", () => {
  it("三件必填 + preset 纯 string（去 enum，描述诚实）", () => {
    const params = paramsOf("ws_request_verdict");
    expect(params["required"]).toEqual(["preset_id", "state", "questions_override"]);
    const preset = (params["properties"] as Record<string, Record<string, unknown>>)["preset_id"];
    expect(preset["type"]).toBe("string");
    expect(preset["enum"]).toBeUndefined();
    const desc = preset["description"] as string;
    for (const noun of [
      "general",
      "secret-leak",
      "plan-review",
      "risk-check",
      "custom",
      "ws_list_verdict_guides",
    ]) {
      expect(desc).toContain(noun);
    }
  });
  it("state 与题目 items 的约束落在 schema 里", () => {
    const params = paramsOf("ws_request_verdict");
    const props = params["properties"] as Record<string, Record<string, unknown>>;
    const state = props["state"];
    expect(state["required"]).toEqual(["text"]);
    const lang = (state["properties"] as Record<string, Record<string, unknown>>)["lang"];
    expect(lang["enum"]).toEqual(["en", "zh", "unknown"]);
    expect(lang["default"]).toBe("unknown");
    const override = props["questions_override"];
    const items = override["items"] as Record<string, unknown>;
    expect(items["required"]).toEqual(["id", "text", "kind"]);
    const kind = (items["properties"] as Record<string, Record<string, unknown>>)["kind"];
    expect(kind["enum"]).toEqual(["choice", "score"]);
  });
  it("每级属性都有非空说明（顶层 + state + 题目 items）", () => {
    const params = paramsOf("ws_request_verdict");
    const top = params["properties"] as Record<string, Record<string, unknown>>;
    for (const key of ["preset_id", "state", "questions_override"]) {
      expect(typeof top[key]["description"]).toBe("string");
      expect((top[key]["description"] as string).length).toBeGreaterThan(0);
    }
    const stateProps = top["state"]["properties"] as Record<string, Record<string, unknown>>;
    for (const key of ["text", "lang"]) {
      expect((stateProps[key]["description"] as string).length).toBeGreaterThan(0);
    }
    const itemProps = (top["questions_override"]["items"] as Record<string, unknown>)[
      "properties"
    ] as Record<string, Record<string, unknown>>;
    for (const key of ["id", "text", "kind", "options"]) {
      expect((itemProps[key]["description"] as string).length).toBeGreaterThan(0);
    }
  });
});

describe("list 描述指回 decide", () => {
  it("只读语义 + 前置调用指引", () => {
    const tool = definitions().find((d) => d.name === "ws_list_verdict_guides");
    expect(tool).toBeDefined();
    const text = (tool as unknown as { description: string }).description;
    expect(text).toContain("read-only");
    expect(text).toContain("ws_request_verdict");
    expect(text).toContain("automationCap");
  });
});

/** BaseURL 防篡改：写死常量 + 退役键拒收 + 迁移剥离 + 出境 URL 精确（全离线）。
 *
 * 守的是 shared/contract.JEV_BASE_URL 与 config 退役键面：把基址改掉、PUT 放行 baseUrl、
 * 迁移漏剥任一改动，本文件必红。fetch 经注入捕获 URL，不触网。
 */
import { describe, expect, it } from "vitest";
import { normalizeLoadedConfig, validatePutBody } from "../../src/server/config/impl/model.ts";
import { decide } from "../../src/server/tools/impl/service.ts";
import type { DecideDeps } from "../../src/server/tools/deps.ts";
import { JEV_BASE_URL, JEV_MODEL } from "../../src/shared/contract.ts";

const EXPECTED_BASE = "https://api.typesafe.ai/v1/systemone";
const CONNECTION = {
  timeoutMs: 8000,
  maxConcurrency: 4,
  truncBudget: 32000,
  hasPlaintextKey: false,
} as const;

describe("BaseURL 写死", () => {
  it("常量即官方基址字面量（第二事实源手写）", () => {
    expect(JEV_BASE_URL).toBe(EXPECTED_BASE);
  });
  it("模型即冻结别名 jev-latest（与基址同等 pin 待遇）", () => {
    expect(JEV_MODEL).toBe("jev-latest");
  });
  // 注：退役键表成员由下条 PUT 逐键拒收断言覆盖（删表项即 UNKNOWN_KEY 而非 RETIRED_KEY），不另立表断言（去装饰）。
  it("PUT 遇退役键一律 RETIRED_KEY（顶层/connection/history 均拒）", () => {
    for (const key of ["baseUrl", "apiBaseUrl", "endpoint", "apiEndpoint", "url"]) {
      const r = validatePutBody({ [key]: "https://evil.example" });
      expect(r.ok).toBe(false);
      if (!r.ok) expect(r.failure.errorCode).toBe("RETIRED_KEY");
    }
    const nested = validatePutBody({ history: { perSession: 200, totalSessions: 50 } });
    expect(nested.ok).toBe(true);
  });
  it("加载迁移剥离退役键并告警名单", () => {
    const { config, retired } = normalizeLoadedConfig({
      connection: { baseUrl: "https://evil.example" },
      presets: [],
      history: {},
    });
    expect(retired).toContain("baseUrl");
    expect(config.version).toBe(1);
    expect(JSON.stringify(config)).not.toContain("evil.example");
  });
  it("出境 URL 精确等于基址（篡改即红）", async () => {
    let seenUrl = "";
    const deps: DecideDeps = {
      logger: { warn: () => {} },
      connection: { ...CONNECTION },
      isEnabled: () => true,
      capOf: () => 2,
      resolveKey: () => ({ key: "Abcdefgh12345678", source: "env" as const }),
      root: "/tmp/proj",
      sessionId: "sess-1",
      signal: new AbortController().signal,
      fetchImpl: async (url) => {
        seenUrl = url;
        return {
          status: 200,
          text: JSON.stringify({
            model: "jev-1.13.0",
            answers: {
              q1: {
                type: "choice",
                choice: "A",
                confidence: 0.9,
                probabilities: { A: 0.9, B: 0.1 },
              },
            },
            usage: { input_tokens: 9, output_tokens: 3 },
          }),
        };
      },
    };
    const out = await decide(
      {
        preset_id: "general",
        state: { text: "hi", lang: "en" },
        questions_override: [{ id: "q1", text: "Pick one.", kind: "choice", options: ["A", "B"] }],
      },
      deps,
    );
    expect(out.ok).toBe(true);
    expect(seenUrl).toBe(EXPECTED_BASE);
    expect(seenUrl).toBe(JEV_BASE_URL);
  });
});
